def shortest_path_length(length_by_edge, startnode, goalnode):
    unvisited_nodes = []
    heappush(unvisited_nodes, (0, startnode))
    visited_nodes = set()
    distances = {startnode: 0}

    while unvisited_nodes:
        distance, node = heappop(unvisited_nodes)

        if node in visited_nodes:
            continue

        if node == goalnode:
            return distance

        visited_nodes.add(node)

        for nextnode in node.successors:
            if nextnode in visited_nodes:
                continue

            new_distance = distance + length_by_edge[node, nextnode]

            if new_distance < distances.get(nextnode, float('inf')):
                distances[nextnode] = new_distance
                heappush(unvisited_nodes, (new_distance, nextnode))

    return float('inf')

from heapq import *

def shortest_path_length(length_by_edge, startnode, goalnode):
    unvisited_nodes = []
    heappush(unvisited_nodes, (0, startnode))
    visited_nodes = set()

    while len(unvisited_nodes) > 0:
        distance, node = heappop(unvisited_nodes)
        if node == goalnode:
            return distance

        visited_nodes.add(node)

        for nextnode in node.successors:
            if nextnode in visited_nodes:
                continue

            candidate_distance = distance + length_by_edge[node, nextnode]
            existing_distance = get(unvisited_nodes, nextnode)

            if existing_distance is None or candidate_distance < existing_distance:
                insert_or_update(unvisited_nodes, (candidate_distance, nextnode))

    return float('inf')


def get(node_heap, wanted_node):
    for dist, node in node_heap:
        if node == wanted_node:
            return dist
    return None


def insert_or_update(node_heap, dist_node):
    dist, node = dist_node
    for i, tpl in enumerate(node_heap):
        a, b = tpl
        if b == node:
            node_heap[i] = dist_node
            heapify(node_heap)
            return None

    heappush(node_heap, dist_node)
    return None

def wrap(text, cols):
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end == -1:
            end = cols
        line, text = text[:end], text[end:]
        lines.append(line)

    if text:
        lines.append(text)

    return lines
